PAIR_RUN_ID='e846ecf57f8f48b8871514a9badca2d0'
MODULES={'runtime': {'sha256': 'd73dc91bcc714b60b9d2f35bb11df2d2590d6a27e90a94bf0aff0325fc3d5003', 'z64': ''}, 'cohort': {'sha256': '5d0cd8d4cf45b8301532517af832710c3928458f20c1cc64b0991500ddb1b89d', 'z64': ''}, 'replay': {'sha256': '780779b6d3f2c6ea2b7c4a6115d193b9d4116b654251149bac1cc5e0d004d20e', 'z64': ''}, 'pair': {'sha256': '281df1911000fbd8697f021b791809f309afe644ea35ff569143e117a80b2f35', 'z64': ''}}
"""One actual Guest per node: restore, bind, read, retain for peer isolation.

No provider allocation/retirement, local-lower copy, cache eviction or service
changes. Unknown mutations remain journalled; this entry never retries them.
"""
import argparse,base64,fcntl,hashlib,json,os,re,shlex,shutil,stat,subprocess,sys,time,types,uuid,zlib
from pathlib import Path
ROOT=Path('/home/jwk/agent')
D=ROOT/'deployments/agentenv-direct-ub-deletefix-v1'
WORK=D/'acceptance/exit-pair-v1'
DEPLOY_SHA='b879e57841935e4516a28badf7e7f32ccaf53c94e5f6721ef7b803afb489ac65'

def need(ok,reason):
    if not ok:raise RuntimeError(reason)

def module(name):
    item=MODULES[name];raw=zlib.decompress(base64.b64decode(item['z64'],validate=True))
    need(hashlib.sha256(raw).hexdigest()==item['sha256'],'Embedded helper differs')
    m=types.ModuleType(name);m.__file__=str(WORK/(name+'.py'))
    exec(compile(raw,m.__file__,'exec'),m.__dict__);return m

def save(path,value,uid=0,gid=0):
    need(path.parent.resolve(strict=True)==path.parent and path.is_relative_to(D),'Output path differs')
    temp=path.with_name(path.name+'.'+uuid.uuid4().hex+'.tmp')
    fd=os.open(temp,os.O_WRONLY|os.O_CREAT|os.O_EXCL|os.O_NOFOLLOW,0o600)
    with os.fdopen(fd,'wb') as out:
        os.fchown(out.fileno(),uid,gid)
        out.write((json.dumps(value,indent=2)+'\n').encode());out.flush();os.fsync(out.fileno())
    os.replace(temp,path)
    fd=os.open(path.parent,os.O_RDONLY|os.O_DIRECTORY)
    try:os.fsync(fd)
    finally:os.close(fd)

def process(pid,expected,cgroup):
    proc=Path('/proc')/str(pid)
    before=(proc/'stat').read_text().rsplit(')',1)[1].split()[19]
    need((proc/'exe').resolve(strict=True)==expected,'Process executable differs')
    actual=os.stat(proc/'exe');disk=expected.stat()
    need((actual.st_dev,actual.st_ino)==(disk.st_dev,disk.st_ino),'Running binary inode differs')
    fields=dict(line.split(':',1) for line in (proc/'status').read_text().splitlines() if ':' in line)
    need([int(x) for x in fields['Uid'].split()]==[1204]*4,'Process UID differs')
    groups=[line.split(':',2)[2] for line in (proc/'cgroup').read_text().splitlines()]
    need(any(g==cgroup or g.startswith(cgroup+'/') for g in groups),'Process not in new Runtime cgroup')
    need((proc/'stat').read_text().rsplit(')',1)[1].split()[19]==before,'Process changed')
    return {'pid':pid,'startTicks':before,'executable':str(expected)}

def find_processes(expected,cgroup):
    found=[]
    for proc in Path('/proc').iterdir():
        if not proc.name.isdigit():continue
        try:
            if os.readlink(proc/'exe')!=str(expected):continue
            groups=[line.split(':',2)[2] for line in (proc/'cgroup').read_text().splitlines()]
            if not any(g==cgroup or g.startswith(cgroup+'/') for g in groups):continue
            found.append(process(int(proc.name),expected,cgroup))
        except (FileNotFoundError,ProcessLookupError):continue
    return found

def trace_summary(path,status_path,pid,image,refs,through_ns):
    need(path.resolve(strict=True)==path and path.stat().st_size<=64*1024**2,'Trace path/budget differs')
    status=json.loads(status_path.read_text())
    need(status['pid']==pid and status.get('read_tracking_version')==1,'Trace process/version differs')
    need(all(status.get(k)==0 for k in ('dropped_records','errors','unsupported_context_calls','repository_fallback_reads','failed_or_cancelled_reads')),
         'Trace incomplete, fallback or failed I/O; preserve diagnostics')
    need(isinstance(status.get('drained_through_ns'),int) and status['drained_through_ns']>=through_ns,'Trace not yet drained')
    count=total=0;digests=set()
    committed=status.get('bytes_written')
    need(type(committed) is int and 0<committed<=64*1024**2,'Trace committed prefix invalid')
    with path.open('rb') as stream:
        data=stream.read(committed)
    need(len(data)==committed and data.endswith(b'\n'),'Trace committed prefix incomplete')
    lines=data.splitlines()
    header=json.loads(lines[0]);need(header.get('kind')=='header' and header.get('pid')==pid,'Trace header differs')
    for line in lines[1:]:
        row=json.loads(line)
        if row.get('source')!=str(image):continue
        if row.get('kind')!='content_read':continue
        need(row.get('from_ub') is True and row.get('allowed_lower') is True,'Actual rootfs read used fallback/unapproved content')
        need(row['digest'] in refs and row['file_bytes']==refs[row['digest']]['fileBytes'],'Trace lower identity differs')
        need(0<=row['offset'] and row['bytes']>0 and row['offset']+row['bytes']<=row['file_bytes'],'Trace read range differs')
        count+=1;total+=row['bytes'];digests.add(row['digest'])
    need(count>0,'No real UB rootfs reads attributed to this Guest')
    return {'requests':count,'bytesIncludingRepeatedReads':total,'digestsRead':sorted(digests),
            'source':str(image),'trace':str(path),'traceStatus':status,
            'scope':'actual lower I/O during restore and command; not every Guest read causes backend I/O'}

class ReadyRun:
    def __init__(self):
        need(os.getuid()==os.geteuid()==0 and sys.platform=='linux','Run scoped observation as root on target')
        raw=(D/'libexec/direct_guest_runtime.py').read_bytes()
        need(hashlib.sha256(raw).hexdigest()==DEPLOY_SHA,'Installed deployment entry differs')
        self.deploy=types.ModuleType('pinned_deployment');self.deploy.__file__=str(D/'libexec/direct_guest_runtime.py')
        exec(compile(raw,self.deploy.__file__,'exec'),self.deploy.__dict__)
        self.n=self.deploy.node();self.definition=self.deploy.load(D/'guest-definition.json')
        need(self.definition['node']==self.n,'Wrong deployed node')
        self.m=self.deploy.make_module(self.definition);self.m.installed()
        self.provider=self.deploy.check_provider(self.n)
        need(self.provider==self.definition['ub'],'Provider identity/index changed')
        self.rt=module('runtime');self.rt.ROOT=ROOT
        self.engine=module('cohort');self.pair=module('pair');self.replay=module('replay')
        self.api=self.rt.Api(D,self.m.UNIT,self.definition['apiPort'])
        self.original_units=self.deploy.preserve_units(self.m,self.n)
        self.binaries={}
        for name,row in {**self.deploy.CORE_ARTIFACTS,**self.deploy.RETAINED_ARTIFACTS}.items():
            if name in ('server','uvm-ublk-daemon','aenv'):path=D/'bin'/name
            elif name=='firecracker':path=D/'deps/firecracker/1.15.1-patch-v3/firecracker'
            else:continue
            need(self.rt.digest_file(path)==row['sha256'],'Deployed binary differs: '+name)
            self.binaries[name]={'path':str(path),'sha256':row['sha256'],'bytes':path.stat().st_size}
        self.server=process(self.api.pid,D/'bin/server',self.api.cgroup)
        self.record=self.deploy.load(D/'state/snapshot-store/repository/catalog/records'/(self.deploy.TEMPLATE+'.json'))
        need(hashlib.sha256(self.deploy.read(D/'state/snapshot-store/repository/catalog/records'/(self.deploy.TEMPLATE+'.json'))).hexdigest()==self.deploy.CATALOG_SHA,'Template changed')
        self.lowers=[r['Managed'] for r in self.record['committed']['rootfs_layers']]
        self.index=self.deploy.load(self.provider['path'])
        self.refs={r['layerDigest']:r for r in self.index['replicas']}
        self.case=None;self.command_pending=None

    def persist(self,state):
        save(WORK/'state.json',state)
        save(D/'guest-cohort-state.json',{'version':1,'phase':state['phase'],
            'openRequests':state['openRequests'],'sandboxIds':state['sandboxIds'],
            'outcomeUncertain':bool(state['openRequests']),'directPairRunId':state['runId']},1204,1205)

    def guard(self):
        self.api.stable()
        need(self.deploy.check_provider(self.n)==self.provider,'Provider changed')
        need(process(self.api.pid,D/'bin/server',self.api.cgroup)==self.server,'Server changed')
        need(self.deploy.preserve_units(self.m,self.n)==self.original_units,'An existing unit changed')

    def capacity(self,kind):
        self.guard()
        fields=dict(line.split(':',1) for line in Path('/proc/meminfo').read_text().splitlines())
        need(int(fields['MemAvailable'].split()[0])*1024>=8*1024**3,'Need 8GiB available for one 4GiB Guest')
        need(shutil.disk_usage(ROOT).free>=8*1024**3,'Need 8GiB free; no cleanup attempted')
        limit=int(Path('/sys/module/ublk_drv/parameters/ublks_max').read_text())
        used=sum(bool(re.fullmatch(r'ublkc\d+',p.name)) for p in Path('/sys/class/ublk-char').iterdir())
        need(limit-used>=4,'Insufficient free ublk slots; no existing devices changed')

    def observe(self,sid):
        self.guard();need(self.case.owned(sid) is not None,'Owned Guest missing')
        fcpath=Path(self.binaries['firecracker']['path'])
        matches=[]
        for item in find_processes(fcpath,self.api.cgroup):
            proc=Path('/proc')/str(item['pid'])
            if os.readlink(proc/'fd/2')==str(D/'logs/firecracker'/sid/'firecracker-stderr.log'):matches.append(item)
        need(len(matches)==1,'Expected one exact owned FC process')
        fc=matches[0];proc=Path('/proc')/str(fc['pid']);cwd=(proc/'cwd').resolve(strict=True)
        need(cwd.is_relative_to(self.deploy.location(self.n)[1]) and cwd.name.startswith('agentenv-fc-'),'FC working directory differs')
        image=cwd/'overlaybd/image.json';raw=self.deploy.read(image);config=json.loads(raw)
        self.pair.binding(config,self.lowers,self.index)
        upper={}
        for kind in ('data','index'):
            path=Path(config['upper'][kind]);path=path if path.is_absolute() else image.parent/path
            need(path.resolve(strict=True)==path and path.is_relative_to(cwd),'Upper outside private Guest directory')
            meta=path.stat();need(stat.S_ISREG(meta.st_mode) and meta.st_uid==1204 and meta.st_nlink==1,'Upper ownership/type/link differs')
            upper[kind]={'path':str(path),'dev':meta.st_dev,'inode':meta.st_ino,'bytes':meta.st_size,'mtimeNs':meta.st_mtime_ns}
        device=(cwd/'user-rootfs').resolve(strict=True)
        need(re.fullmatch('/dev/ublkb[0-9]+',str(device)) and stat.S_ISBLK(device.stat().st_mode),'Guest rootfs is not an ublk block device')
        rdev=device.stat().st_rdev;opened=False
        for fd in (proc/'fd').iterdir():
            try:
                meta=fd.stat()
                opened|=stat.S_ISBLK(meta.st_mode) and meta.st_rdev==rdev
            except FileNotFoundError:continue
        need(opened,'FC does not hold the bound rootfs block device')
        daemons=find_processes(D/'bin/uvm-ublk-daemon',self.api.cgroup)
        need(len(daemons)==1,'Expected one exact new storage daemon')
        need(process(fc['pid'],fcpath,self.api.cgroup)==fc,'FC identity changed during observation')
        return {'sandboxId':sid,'fcIdentity':fc,'daemonIdentity':daemons[0],
            'imageConfigPath':str(image),'imageConfigSha256':hashlib.sha256(raw).hexdigest(),
            'bindingVerified':True,'lowerCount':len(self.lowers),'requiredUB':True,'upperPrivateVerified':True,
            'upper':upper,'rootfsDevice':str(device),'rootfsDeviceMajor':os.major(rdev),'rootfsDeviceMinor':os.minor(rdev)}

    def command(self,sid):
        need(self.case.owned(sid) is not None,'Owned Guest missing')
        marker='DIRECT_UB_END_'+uuid.uuid4().hex
        command=self.replay.shell_command(self.pair.guest_command(PAIR_RUN_ID),marker)
        intent={'label':'base-read','sandboxId':sid,'guestTimeoutSeconds':300,'cliTimeoutSeconds':330,'startedNs':time.time_ns()}
        self.command_pending=intent;save(WORK/'command-intent.json',intent)
        env=self.m.environment();env.update(XDG_CONFIG_HOME=str(D/'cli/config'),XDG_CACHE_HOME=str(D/'cli/cache'))
        args=['/usr/bin/setpriv','--reuid=1204','--regid=1205','--clear-groups','--inh-caps=-all','--ambient-caps=-all','--bounding-set=-all','--no-new-privs',
              str(D/'bin/aenv'),'exec',sid,'/bin/bash','-c',command]
        child=None;start=time.monotonic()
        try:
            with (WORK/'base-read.stdout').open('xb') as out,(WORK/'base-read.stderr').open('xb') as err:
                child=subprocess.Popen(args,env=env,stdin=subprocess.DEVNULL,stdout=out,stderr=err)
                while child.poll() is None:
                    need(time.monotonic()-start<330,'CLI exceeded 330 seconds; command outcome preserved')
                    need(sum((WORK/name).stat().st_size for name in ('base-read.stdout','base-read.stderr'))<=4*1024**2,'CLI output budget exceeded')
                    time.sleep(.2)
            need(child.returncode==0,'CLI transport failed; retain private logs')
            need(sum((WORK/name).stat().st_size for name in ('base-read.stdout','base-read.stderr'))<=4*1024**2,'Completed CLI output budget exceeded')
            text=(WORK/'base-read.stdout').read_text(errors='replace')
            exits=re.findall(r'(?m)^'+marker+r' ([0-9]+)\s*$',text)
            need(len(exits)==1 and exits[0]=='0','Guest command failed; retain private logs')
            result=self.pair.file_result({'exitCode':0,'timedOut':False,'stdout':text})
            save(WORK/'command-result.json',{'result':result,'exitCode':0,'timedOut':False,'seconds':time.monotonic()-start})
            self.command_pending=None;return result
        finally:
            if child is not None and child.poll() is None:
                child.terminate()
                try:child.wait(timeout=5)
                except subprocess.TimeoutExpired:child.kill();child.wait(timeout=5)

    def run(self):
        need(not WORK.exists() and not WORK.is_symlink(),'Existing Guest attempt preserved; do not repeat ready')
        need(self.engine.quiescent(self.deploy.load(D/'guest-cohort-state.json')),'Previous cohort unresolved')
        need(self.api.call('GET','/v2/sandboxes?limit=1')==(200,[]),'New service must be empty before first Guest')
        WORK.parent.mkdir(mode=0o700,exist_ok=True)
        need(WORK.parent.resolve(strict=True)==WORK.parent and WORK.parent.stat().st_uid==0,'Acceptance parent differs')
        WORK.mkdir(mode=0o700)
        lock=os.open(WORK/'run.lock',os.O_WRONLY|os.O_CREAT|os.O_EXCL,0o600)
        fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
        report={'status':'RUNNING','node':self.n,'pairRunId':PAIR_RUN_ID,'coreCommit':self.deploy.CORE_COMMIT,
            'workDirectory':str(WORK),'unit':self.m.UNIT,'apiPort':self.definition['apiPort'],'serverIdentity':self.server,
            'binaries':self.binaries,'provider':self.provider,'GuestAccepted':False,'twoNodeAccepted':False,
            'netSavingsBytes':None,'SDK_allocation_called_by_controller':False,'providerRetained':True}
        try:
            self.case=self.engine.Cohort(self.api,{'version':1,'phase':'prepared','openRequests':[],'sandboxIds':[],
                'outcomeUncertain':False},self.persist,None,None,self.capacity,None,run_id=PAIR_RUN_ID,mutation_guard=self.guard)
            print('PHASE=restore-one-real-guest',flush=True)
            sid=self.case.create('/v2/sandboxes',{'templateID':self.deploy.TEMPLATE,'timeout':7200,'autoPause':False,
                'secure':True,'allow_internet_access':False,'metadata':{'cow_batch':PAIR_RUN_ID,'ub_pair':PAIR_RUN_ID,'ub_pair_node':self.n}})
            report['sandboxId']=sid
            before=self.observe(sid);save(WORK/'binding-before-command.json',before)
            print('PHASE=guest-direct-rootfs-read',flush=True)
            result=self.command(sid);through=time.monotonic_ns()
            observed=self.observe(sid)
            need(observed['fcIdentity']==before['fcIdentity'] and observed['imageConfigSha256']==before['imageConfigSha256'],'Guest binding changed')
            daemon=observed['daemonIdentity'];trace=D/'logs/rootfs-access'/('uvm-ublk-daemon-'+str(daemon['pid'])+'.jsonl')
            status=trace.with_suffix('.status.json')
            for attempt in range(25):
                if status.exists():
                    item=json.loads(status.read_text())
                    if isinstance(item.get('drained_through_ns'),int) and item['drained_through_ns']>=through:break
                time.sleep(.2)
            evidence=trace_summary(trace,status,daemon['pid'],Path(observed['imageConfigPath']),self.refs,through)
            self.guard()
            report.update(status='DIRECT_UB_ONE_REAL_GUEST_READY_RETAINED',base=result,binding=observed,actualUBReads=evidence,
                singleGuestReadAndBindingPassed=True,
                scope='one real restored Guest read and actual backend binding/events; peer isolation and release not yet accepted')
            save(WORK/'ready-receipt.json',{'version':1,'kind':'ready','node':self.n,'runId':PAIR_RUN_ID,
                'ownerId':self.deploy.OWNER,'manifestSha256':self.deploy.MANIFEST,'templateId':self.deploy.TEMPLATE,
                'sandboxId':sid,'base':result,'written':None,'guestExitConfirmed':False})
        except Exception as error:
            report.update(status='STOPPED_DIRECT_UB_GUEST_READY_PRESERVE_STATE',errorType=type(error).__name__,
                reason=str(error)[:1000],commandOutcomeUncertain=self.command_pending is not None,
                automaticCleanup=False)
        finally:
            if self.case:report['journal']=self.case.state
            save(WORK/'report.json',report);os.close(lock)
        return report

def main():
    parser=argparse.ArgumentParser(description=__doc__);parser.add_argument('--run',action='store_true');args=parser.parse_args()
    if not args.run:print(json.dumps({'status':'PLAN_ONLY','scope':'restore exactly one real Guest per node; retain for peer tests'}));return 0
    report=ReadyRun().run()
    print('BEGIN_DIRECT_UB_REAL_GUEST_REPORT');print(json.dumps(report,indent=2));print('END_DIRECT_UB_REAL_GUEST_REPORT')
    return 0 if report['status']=='DIRECT_UB_ONE_REAL_GUEST_READY_RETAINED' else 1

if __name__=='__main__':
    try:rc=main()
    except Exception as error:
        print(json.dumps({'status':'STOPPED_DIRECT_UB_GUEST_PREFLIGHT','errorType':type(error).__name__,'reason':str(error)[:1000],'automaticCleanup':False}));rc=1
    raise SystemExit(rc)
